-- Order: batch 0, then 1, then 2 ... 7. Run batch 1 BEFORE deploying the code from this PR
-- (the new code's health check expects zones.area_kind). Each later batch is safe to paste on its own,
-- parents before children, and ends with the layout revision bump the map needs to show changes.
-- These rows are written without events, so the app's Undo cannot remove them: use the rollback file.

-- ===== Batch 0. Read-only pre-checks (change nothing) (9 statements) =====
SELECT name FROM sqlite_master WHERE type='table' ORDER BY name;
PRAGMA table_info(zones); -- before batch 1 there is no area_kind column; after it there is
PRAGMA table_info(shelves); -- must list location_type (migration 0004)
SELECT zone_id, name, room_no, version, active FROM zones WHERE room_no IN ('120','121','122','123') ORDER BY room_no; -- expect exactly one active row per room
SELECT count(*) AS active_shelves FROM shelves WHERE active=1; -- expect 0 real shelves
SELECT s.shelf_id, s.name FROM shelves s WHERE s.active=1 AND lower(s.name) IN ('a1','b1','b2','b3','b4','b5','c1','c2','c3','c4','c5','c6','d1','d2','d3','d4','e1','e2','e3','e4','f1','g1','g2','g3','g4','g5','g6','g7','g8','g9','h1','h2','h3','h4','h5','h6','h7','h8','h9','j1','j2','k1','l1','salt','e4h','c6h'); -- expect no rows
SELECT shelf_id FROM shelves WHERE shelf_id IN ('shf-zarhssgs','shf-kpb33bdc','shf-w44rvf79','shf-g6f3ts2y','shf-g73jsysr','shf-3wd9ra3c','shf-6grqk32t','shf-p8y59sb3','shf-pezwrw2e','shf-8cs68ecm','shf-fx9snavs','shf-vzbrvbmr','shf-j2hdazen','shf-hh44pduh','shf-bxyhncyj','shf-tpw8qcht','shf-sr6hb86u','shf-rz5tf279','shf-6yvsrqv4','shf-ucpq4ddw','shf-ssj7pzad','shf-c8rtwvsp','shf-k9apv9ey','shf-hg9jrqbw','shf-wae33vdw','shf-gbwab54y','shf-zwfuh796','shf-397rnced','shf-6ggm3xpw','shf-fd5hsa7w','shf-reg3b6uv','shf-t8fgk96d','shf-hcgq5uyr','shf-sev7w8bz','shf-n9r4z5vq','shf-tqqn988n','shf-sc6fj2x4','shf-xyrpvcve','shf-azr3n64x','shf-2gh32dg9','shf-3z3avbrq','shf-h723tzrj','shf-3hxyvexp','shf-jtrzp46u','shf-caackbzb','shf-evcrk8xe') UNION ALL SELECT zone_id FROM zones WHERE zone_id IN ('zon-4zbmay56','zon-edscmkeq') UNION ALL SELECT slot_id FROM slots WHERE slot_id='slt-hrhtdd9f'; -- expect no rows (or all rows on a rerun)
SELECT opening_id, tag, x1_in, y1_in, x2_in, y2_in, version, notes FROM openings WHERE opening_id IN ('opn-gqgjbhh4','opn-zh5zkdtw'); -- expect version 1 and the original X values in the rollback file
SELECT revision, updated_at FROM warehouse_meta WHERE id=1;

-- ===== Batch 1. Schema: add zones.area_kind (same as migrations/0005_zone_area_kind.sql). Run once; a rerun fails with 'duplicate column name', which is harmless. (1 statement) =====
ALTER TABLE zones ADD COLUMN area_kind TEXT CHECK(area_kind IN ('tools','packouts'));

-- ===== Batch 2. Wall corrections (openings). Each UPDATE only matches the original row at version 1, so a rerun changes nothing. (3 statements) =====
UPDATE openings SET x1_in=60.5, y1_in=1683, x2_in=111.5, y2_in=1683, notes='Moved to the west end: on the sketch the printed opening (X 381.5-421.5) is filled in and the wall at X 60.5-111.5 is taped out. Position UNVERIFIED', version=version+1 WHERE opening_id='opn-gqgjbhh4' AND version=1 AND x1_in=381.5 AND x2_in=421.5 AND active=1;
UPDATE openings SET x1_in=110.5, y1_in=1443, x2_in=279, y2_in=1443, notes='Widened from the sketch: the stub wall is taped out from X 110.5, and a short wall is drawn at X 279-314.5 against 122. Printed 8'' at the stub wall. Position UNVERIFIED', version=version+1 WHERE opening_id='opn-zh5zkdtw' AND version=1 AND x1_in=218.5 AND x2_in=314.5 AND active=1;
UPDATE warehouse_meta SET revision = revision + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE id = 1;

